{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Telbivudine, the closest structural analogue (thymidine nucleoside with a saturated sugar), has an absolute oral bioavailability of ~52% in subjects with normal renal function, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Zidovudine, a thymine-based nucleoside analogue sharing the same base and dideoxy-sugar-like scaffold, has an absolute oral bioavailability of 64% ± 21.3% in HIV-infected patients, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Azidothymidine (zidovudine) showed 63% ± 13% oral bioavailability in AIDS patients, providing additional direct evidence that this nucleoside class is well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Sorivudine, another 5-substituted uracil nucleoside analogue, has an absolute oral bioavailability of approximately 60% in volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Even the least-absorbed close analogue, 882C87, has an absolute oral bioavailability of 24.6% in elderly subjects, remaining above the 20% threshold and supporting a high prediction.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved nucleoside analogues with relevant experimental oral bioavailability data show F values at or above ~20%, with most well above 50%. The closest analogue, telbivudine, has ~52% absolute bioavailability, and the thymine-nucleoside class consistently supports high oral bioavailability for the query.",
  "evidence_gaps": [
    "No direct experimental record for stavudine itself is present in the provided evidence; prediction relies on close nucleoside analogues.",
    "Some records report extent of absorption or unspecified bioavailability rather than strictly absolute F, though multiple absolute oral bioavailability records are available for key analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

